        let manifest: OciManifest = response.json().await.map_err(|e| {
            CleanroomError::report_error(format!("Failed to parse manifest: {}", e))
        })?;

        Ok(manifest)
    }

    /// Fetch blob (config or layer)
    async fn fetch_blob(
        &self,
        registry: &str,
        repository: &str,
        digest: &str,
