mod tests {
    use super::*;

    #[test]
    fn test_validation_analysis_from_report() {
        let report = WeaverValidationReport {
            advice_level_counts: AdviceCounts {
                violation: 0,
                improvement: 2,
                information: 5,
            },
            registry_coverage: 0.92,
