            ]),
            seen_non_registry_attributes: HashMap::new(),
        };

        let analysis = ValidationAnalysis::from_report(report).unwrap();

        assert!(analysis.passed);
        assert_eq!(analysis.total_violations, 0);
        assert_eq!(analysis.coverage, 0.92);
