            PathBuf::from("validation_output/"),
        );

        assert!(manager.is_ok());
        let manager = manager.unwrap();
        assert_eq!(manager.otlp_port, None);
        assert_eq!(manager.admin_port, None);
        assert_eq!(manager.pid(), None);
